mapper.select:
SELECT VOUCHER_ID, VOUCHER_NO, VOUCHER_TYPE_ID, VOUCHER_DATE, ACCOUNTING_PERIOD, VOUCHER_DESC, TOTAL_DEBIT, TOTAL_CREDIT, VOUCHER_STATUS, AUDIT_STATUS, AUDITOR, AUDIT_TIME, BOOK_ID, TENANT_ID, VERSION, CREATE_TIME, UPDATE_TIME, CREATOR, UPDATER FROM T_ACCOUNTING_VOUCHER WHERE IS_DELETED = 0
AND TENANT_ID = #{param.tenantId}
AND BOOK_ID = #{param.bookId}
AND VOUCHER_NO LIKE '%' || #{param.voucherNo} || '%'
AND VOUCHER_TYPE_ID = #{param.voucherTypeId}
AND VOUCHER_DATE >= #{param.voucherDateStart}
AND VOUCHER_DATE <= #{param.voucherDateEnd}
AND ACCOUNTING_PERIOD = #{param.accountingPeriod}
AND VOUCHER_STATUS = #{param.voucherStatus}
AND AUDIT_STATUS = #{param.auditStatus}
AND AUDITOR = #{param.auditor}

mapper.update:
UPDATE T_ACCOUNTING_VOUCHER SET IS_DELETED = 1, UPDATER = #{updater}, UPDATE_TIME = SYSDATE WHERE VOUCHER_ID IN
#{id}
AND IS_DELETED = 0

UPDATE T_ACCOUNTING_VOUCHER SET VOUCHER_STATUS = #{voucherStatus}, UPDATER = #{updater}, UPDATE_TIME = SYSDATE WHERE VOUCHER_ID IN
#{id}
AND IS_DELETED = 0

mapper.select:
SELECT DISTINCT VOUCHER_TYPE_ID
FROM T_ACCOUNTING_VOUCHER
WHERE BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND IS_DELETED = 0
AND VOUCHER_TYPE_ID IS NOT NULL
